function getFirstMonday(year, month) {
  const date2 = new Date(year, month - 1, 1);
  const day = date2.getDay();
  const diff = day === 0 ? 1 : day === 1 ? 0 : 8 - day;
  date2.setDate(date2.getDate() + diff);
  return date2.toISOString().split("T")[0];
}
function getSecondMonday(year, month) {
  const first = new Date(getFirstMonday(year, month));
  first.setDate(first.getDate() + 7);
  return first.toISOString().split("T")[0];
}
function getThirdMonday(year, month) {
  const first = new Date(getFirstMonday(year, month));
  first.setDate(first.getDate() + 14);
  return first.toISOString().split("T")[0];
}
function getLastMonday(year, month) {
  const date2 = new Date(year, month, 0);
  const day = date2.getDay();
  const diff = day >= 1 ? day - 1 : 6;
  date2.setDate(date2.getDate() - diff);
  return date2.toISOString().split("T")[0];
}
function getFourthThursday(year, month) {
  const date2 = new Date(year, month - 1, 1);
  const day = date2.getDay();
  const diff = day <= 4 ? 4 - day : 11 - day;
  date2.setDate(date2.getDate() + diff + 21);
  return date2.toISOString().split("T")[0];
}
function getDayAfterThanksgiving(year) {
  const thanksgiving = new Date(getFourthThursday(year, 11));
  thanksgiving.setDate(thanksgiving.getDate() + 1);
  return thanksgiving.toISOString().split("T")[0];
}
function getEasterDate(year) {
  const a = year % 19;
  const b = Math.floor(year / 100);
  const c = year % 100;
  const d = Math.floor(b / 4);
  const e = b % 4;
  const f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4);
  const k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const month = Math.floor((h + l - 7 * m + 114) / 31);
  const day = (h + l - 7 * m + 114) % 31 + 1;
  return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}
