      async getCoursesByDepartment(department) {
        const courseIds = await db.select({ courseId: lmsCourseDepartments.courseId }).from(lmsCourseDepartments).where(eq5(lmsCourseDepartments.department, department));
        if (courseIds.length === 0) return [];
        return db.select().from(lmsCourses).where(and2(
          inArray(lmsCourses.id, courseIds.map((c) => c.courseId)),
          sql6`${lmsCourses.status} = 'published'`
        )).orderBy(lmsCourses.sortOrder);
      }
      async getRequiredCoursesByDepartment(department) {
        const courseIds = await db.select({ courseId: lmsCourseDepartments.courseId }).from(lmsCourseDepartments).where(and2(
          eq5(lmsCourseDepartments.department, department),
          eq5(lmsCourseDepartments.isRequired, true)
        ));
        if (courseIds.length === 0) return [];
        return db.select().from(lmsCourses).where(and2(
          inArray(lmsCourses.id, courseIds.map((c) => c.courseId)),
          sql6`${lmsCourses.status} = 'published'`
        )).orderBy(lmsCourses.sortOrder);
      }
