    b2bCustomerLocations: [],
    b2bCustomerManualProducts: [],
    b2bOrders: [],
    b2bOrderItems: [],
    b2bSlideshowSlides: [],
    b2bAdmins: [],
    b2bSettings: [],
    b2bCommissions: [],
    b2bEmailTemplates: [],
    b2bEmailAutomationLogs: [],
    userGroups: [],
    platformUsers: [],
    platformModules: [],
    moduleFeatures: [],
    groupModuleAccess: [],
    groupFeaturePermissions: [],
    errors: [],
