// server/crypto.ts
import crypto2 from "crypto";
var ALGORITHM = "aes-256-gcm";
var IV_LENGTH = 16;
function getEncryptionKey() {
  const key = process.env.PORTAL_ENCRYPTION_KEY;
  if (!key) {
    console.warn("PORTAL_ENCRYPTION_KEY not set - using fallback key (not recommended for production)");
    return crypto2.scryptSync("default-dev-key-change-in-production", "salt", 32);
  }
  return crypto2.scryptSync(key, "nashoba-salt", 32);
}
function encryptPassword(plaintext) {
  if (!plaintext) return "";
  const key = getEncryptionKey();
  const iv = crypto2.randomBytes(IV_LENGTH);
  const cipher = crypto2.createCipheriv(ALGORITHM, key, iv);
  let encrypted = cipher.update(plaintext, "utf8", "hex");
  encrypted += cipher.final("hex");
  const authTag = cipher.getAuthTag();
  return iv.toString("hex") + ":" + authTag.toString("hex") + ":" + encrypted;
}
function decryptPassword(encryptedData) {
  if (!encryptedData || !encryptedData.includes(":")) return encryptedData || "";
  try {
    const key = getEncryptionKey();
    const parts = encryptedData.split(":");
    if (parts.length !== 3) return "";
    const iv = Buffer.from(parts[0], "hex");
    const authTag = Buffer.from(parts[1], "hex");
    const encrypted = parts[2];
    const decipher = crypto2.createDecipheriv(ALGORITHM, key, iv);
    decipher.setAuthTag(authTag);
    let decrypted = decipher.update(encrypted, "hex", "utf8");
    decrypted += decipher.final("utf8");
    return decrypted;
  } catch (error) {
    console.error("Failed to decrypt password:", error);
    return "";
  }
}

