router4.get("/api/b2b/customer/products", requireB2bAuth, async (req, res) => {
  try {
    let customerId = req.session.b2bUserId;
    const isAdmin5 = req.session.b2bUserType === "admin";
    const isSalesRep = req.session.b2bUserType === "sales_rep";
    if ((isAdmin5 || isSalesRep) && req.query.customerId) {
      customerId = req.query.customerId;
      if (isSalesRep) {
        const customer2 = await storage.getB2bCustomer(customerId);
        if (!customer2 || customer2.salesRepId !== req.session.b2bUserId) {
          return res.status(403).json({ error: "You can only view products for customers assigned to you" });
        }
      }
    } else if (!isAdmin5 && !isSalesRep && req.session.b2bUserType !== "customer") {
      return res.status(403).json({ error: "Access denied" });
    }
    const customer = await storage.getB2bCustomer(customerId);
    if (!customer || !customer.tier) {
      return res.status(400).json({ error: "Customer tier not assigned" });
    }
    const allProducts = await storage.getProducts();
    const allTiers = await storage.getAllTierPricing();
    const customerTierName = customer.tier.tierName;
    const productsWithTierPricing = allProducts.map((product) => {
      const effectiveTier = allTiers.find(
        (t) => t.tierName === customerTierName && t.category === product.category && t.active
      );
      if (effectiveTier) {
        const tierDiscount = parseFloat(effectiveTier.discountPercentage) / 100;
        const basePrice = parseFloat(product.wholesaleOverridePrice || product.price);
        const tierPrice = basePrice * (1 - tierDiscount);
        return {
          ...product,
          tierPrice: tierPrice.toFixed(2)
        };
      }
      return product;
    });
    res.json({ products: productsWithTierPricing, tier: customerTierName });
  } catch (error) {
    console.error("Error fetching products:", error);
    res.status(500).json({ error: "Failed to fetch products" });
  }
});
