router4.post("/api/b2b/sales-rep/orders/place", requireB2bSalesRep, async (req, res) => {
  try {
    const { customerId, items, notes, sendCustomerEmail = true } = req.body;
    const salesRepId = req.session.b2bUserId;
    if (!customerId || !items || !Array.isArray(items) || items.length === 0) {
      return res.status(400).json({ error: "Customer and at least one item are required" });
    }
    const customer = await storage.getB2bCustomer(customerId);
    if (!customer) {
      return res.status(404).json({ error: "Customer not found" });
    }
    if (customer.salesRepId !== salesRepId) {
      return res.status(403).json({ error: "You can only place orders for customers assigned to you" });
    }
    let customerTierName = "";
    if (customer.tier && typeof customer.tier === "object" && "tierName" in customer.tier) {
      customerTierName = customer.tier.tierName;
    }
    if (!customerTierName && customer.pricingTierId) {
      const tierData = await db.select().from(tierPricing).where(eq6(tierPricing.id, customer.pricingTierId));
      if (tierData.length > 0) {
        customerTierName = tierData[0].tierName;
      }
    }
    const productIds = items.map((item) => item.productId);
    const productsData = await db.select().from(products).where(inArray2(products.id, productIds));
    const allTiers = await db.select().from(tierPricing);
    let subtotal = 0;
    let totalDiscount = 0;
    const orderItems = [];
    for (const item of items) {
      const product = productsData.find((p) => p.id === item.productId);
      if (!product) {
        return res.status(404).json({ error: `Product ${item.productId} not found` });
      }
      let discountPercentage = 0;
      if (customerTierName) {
        const matchingTier = allTiers.find(
          (t) => t.tierName === customerTierName && t.category === product.category && t.active
        );
        if (matchingTier) {
          discountPercentage = parseFloat(matchingTier.discountPercentage);
        }
      }
      const basePrice = parseFloat(product.wholesaleOverridePrice || product.price);
      const unitPrice = basePrice * (1 - discountPercentage / 100);
      const lineTotal = unitPrice * item.quantity;
      const lineDiscount = (basePrice - unitPrice) * item.quantity;
      subtotal += lineTotal;
      totalDiscount += lineDiscount;
      orderItems.push({
        productId: product.id,
        productName: product.name,
        productSku: product.sku || "",
        quantity: item.quantity,
        caseSize: product.caseSize || 12,
        unitPrice: unitPrice.toFixed(2),
        retailPrice: basePrice.toFixed(2),
        totalPrice: lineTotal.toFixed(2)
      });
    }
    const orderNumber = `SR-${Date.now()}`;
    const deliveryDateToken = randomBytes(32).toString("hex");
    const deliveryDateTokenExpiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1e3);
    const order = await storage.createB2bOrder({
      customerId,
      orderNumber,
      status: "pending_delivery_date",
      subtotal: (subtotal + totalDiscount).toFixed(2),
      tax: "0",
      total: subtotal.toFixed(2),
      notes: notes || "",
      shippingAddress: customer.shippingAddress || "",
      shippingCity: customer.shippingCity || "",
      shippingState: customer.shippingState || "",
      shippingZipCode: customer.shippingZipCode || "",
      deliveryDateToken,
      deliveryDateTokenExpiresAt
    }, orderItems.map((item) => ({
      productId: item.productId,
      productName: item.productName,
      sku: item.productSku,
      quantity: item.quantity,
      unitPrice: item.unitPrice,
      retailPrice: item.retailPrice,
      lineTotal: item.totalPrice
    })));
    try {
      const { commissionAmount, effectiveRate } = await calculateOrderCommission(salesRepId, subtotal);
      await storage.createCommission({
        orderId: order.id,
        salesRepId,
        orderTotal: subtotal.toFixed(2),
        commissionPercentage: effectiveRate.toFixed(2),
        commissionAmount: commissionAmount.toFixed(2),
        status: "pending"
      });
    } catch (commissionError) {
      console.error("Failed to create commission record:", commissionError);
    }
    try {
      await sendOrderNotifications(order, customer, orderItems.map((item) => ({
        productName: item.productName,
        quantity: item.quantity,
        unitPrice: item.unitPrice,
        lineTotal: item.totalPrice
      })), sendCustomerEmail);
    } catch (emailError) {
      console.error("Failed to send order notifications:", emailError);
    }
    res.json({ success: true, orderId: order.id });
  } catch (error) {
    console.error("Sales rep place order error:", error);
    res.status(500).json({ error: "Failed to place order" });
  }
});
router4.get("/api/b2b/customer/past-orders", requireB2bAuth, async (req, res) => {
  try {
    let customerId = req.session.b2bUserId;
    const isAdmin5 = req.session.b2bUserType === "admin";
    const isSalesRep = req.session.b2bUserType === "sales_rep";
    if ((isAdmin5 || isSalesRep) && req.query.customerId) {
      customerId = req.query.customerId;
      if (isSalesRep) {
        const customer = await storage.getB2bCustomer(customerId);
        if (!customer || customer.salesRepId !== req.session.b2bUserId) {
          return res.status(403).json({ error: "You can only view past orders for customers assigned to you" });
        }
      }
    } else if (!isAdmin5 && !isSalesRep && req.session.b2bUserType !== "customer") {
      return res.status(403).json({ error: "Access denied" });
    }
    if (!customerId) {
      return res.status(401).json({ error: "Not authenticated" });
    }
    const pastOrderItems = await db.select({
      productId: b2bOrderItems.productId,
      productName: b2bOrderItems.productName,
      sku: b2bOrderItems.sku,
      quantity: b2bOrderItems.quantity,
      unitPrice: b2bOrderItems.unitPrice,
      lineTotal: b2bOrderItems.lineTotal,
      caseSize: products.caseSize,
      price: products.price,
      imageUrl: products.imageUrl,
      category: products.category
    }).from(b2bOrderItems).innerJoin(b2bOrders, eq6(b2bOrderItems.orderId, b2bOrders.id)).innerJoin(products, eq6(b2bOrderItems.productId, products.id)).where(
      and3(
        eq6(b2bOrders.customerId, customerId),
        eq6(b2bOrders.status, "completed")
      )
    ).orderBy(desc4(b2bOrders.orderDate));
    const uniqueItems = Array.from(
      new Map(pastOrderItems.map((item) => [item.productId, item])).values()
    );
    res.json(uniqueItems);
  } catch (error) {
    console.error("Error fetching past orders:", error);
    res.status(500).json({ error: "Failed to fetch past orders" });
  }
});
