    const whereClause = sql12`WHERE ${sql12.join(conditions, sql12` AND `)}`;
    const bronzeTier = await db.execute(sql12`SELECT id FROM boomerang_loyalty_tiers WHERE sort_order = 1 LIMIT 1`);
    const tierId = bronzeTier.rows.length > 0 ? bronzeTier.rows[0].id : null;
    const result = await db.execute(sql12`
      INSERT INTO boomerang_loyalty_accounts (toast_guest_id, tier_id, points_balance, lifetime_points)
      SELECT g.id, ${tierId}, 0, 0
      FROM toast_guests g
      LEFT JOIN boomerang_rfm_scores r ON r.toast_guest_id = g.id
      ${whereClause}
      LIMIT ${parseInt(String(batchLimit), 10)}
      RETURNING id
    `);
