router8.post("/automations/:id/simulate", async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) return res.status(400).json({ error: "Invalid automation ID" });
    const rule = await db.execute(sql12`SELECT * FROM boomerang_automation_rules WHERE id = ${id}`);
    if (rule.rows.length === 0) return res.status(404).json({ error: "Automation not found" });
    const r = rule.rows[0];
    const conditions = [sql12`g.merged_into_id IS NULL`];
    const cond = r.conditions;
    if (r.trigger_type === "inactivity" && cond.daysInactive) {
      conditions.push(sql12`g.days_since_last_visit >= ${cond.daysInactive}`);
    }
    if (r.trigger_type === "rfm_segment" && cond.rfmSegment) {
      conditions.push(sql12`rfm.rfm_segment = ${cond.rfmSegment}`);
    }
    if (cond.minSpend) conditions.push(sql12`CAST(COALESCE(g.lifetime_spend, '0') AS FLOAT) >= ${cond.minSpend}`);
    if (cond.minVisits) conditions.push(sql12`COALESCE(g.total_visits, 0) >= ${cond.minVisits}`);
    if (cond.hasEmail) conditions.push(sql12`g.email1 IS NOT NULL AND g.email1 != ''`);
    if (cond.segment) conditions.push(sql12`g.reactivation_segment = ${cond.segment}`);
    const whereClause = conditions.length > 0 ? sql12`WHERE ${sql12.join(conditions, sql12` AND `)}` : sql12``;
    const count2 = await db.execute(sql12`
      SELECT COUNT(*) as eligible
      FROM toast_guests g
      LEFT JOIN boomerang_rfm_scores rfm ON rfm.toast_guest_id = g.id
      ${whereClause}
    `);
    res.json({
      ruleName: r.name,
      eligibleCustomers: Number(count2.rows[0].eligible),
      triggerType: r.trigger_type,
      conditions: r.conditions
    });
  } catch (error) {
    console.error("[Boomerang] Error simulating automation:", error);
    res.status(500).json({ error: "Failed to simulate automation" });
  }
});
