function parseObjectPath2(path4) {
  if (path4.startsWith("https://storage.googleapis.com/")) {
    const url = new URL(path4);
    const parts2 = url.pathname.split("/").filter((p) => p);
    return { bucketName: parts2[0], objectName: parts2.slice(1).join("/") };
  }
  if (!path4.startsWith("/")) path4 = `/${path4}`;
  const parts = path4.split("/");
  return { bucketName: parts[1], objectName: parts.slice(2).join("/") };
}
