// server/growth-studio-routes.ts
init_db();
init_schema();
import { Router as Router16 } from "express";
import { eq as eq15, desc as desc10 } from "drizzle-orm";
import { z as z8 } from "zod";
import OpenAI4 from "openai";
var router16 = Router16();
function getOpenAI() {
  try {
    const apiKey2 = process.env.OPENAI_API_KEY;
    if (!apiKey2) {
      console.log("[Growth Studio] OPENAI_API_KEY not found in env");
      return null;
    }
    return new OpenAI4({ apiKey: apiKey2 });
  } catch (err) {
    console.error("[Growth Studio] Failed to create OpenAI client:", err.message);
    return null;
  }
}
var contentUpdateSchema = z8.object({
  title: z8.string().optional(),
  status: z8.enum(["draft", "saved", "published", "archived"]).optional(),
  selectedVariation: z8.number().int().min(0).optional(),
  channel: z8.string().nullable().optional(),
  targetSegment: z8.string().nullable().optional()
});
var calendarUpdateSchema = z8.object({
  date: z8.string().optional(),
  channel: z8.enum(["email", "sms", "social", "on_site", "print"]).optional(),
  title: z8.string().optional(),
  notes: z8.string().nullable().optional(),
  status: z8.enum(["planned", "published", "cancelled"]).optional()
});
var campaignUpdateSchema = z8.object({
  name: z8.string().optional(),
  status: z8.enum(["draft", "ready", "launched", "completed", "cancelled"]).optional(),
  targetSegment: z8.string().nullable().optional(),
  channels: z8.array(z8.string()).optional(),
  estimatedReach: z8.number().int().nullable().optional()
});
