async function getDefaultChannel() {
  const [channel] = await db.select().from(nashobatvChannels).where(eq16(nashobatvChannels.isActive, true)).orderBy(asc2(nashobatvChannels.id)).limit(1);
  if (channel) return channel;
  return ensureDefaultChannel();
}
