    const displayName = platformUser ? platformUser.firstName || platformUser.lastName ? `${platformUser.firstName || ""} ${platformUser.lastName || ""}`.trim() : agent.email?.split("@")[0] || "Agent" : agent.displayName || agent.email?.split("@")[0] || "Agent";
