  app2.post("/api/admin/product-media/upload", isAdmin5, async (req, res) => {
    try {
      const multer4 = (await import("multer")).default;
      const upload3 = multer4({ storage: multer4.memoryStorage() });
      upload3.single("file")(req, res, async (err) => {
        if (err) {
          return res.status(400).json({ message: "File upload failed" });
        }
        const file = req.file;
        if (!file) {
          return res.status(400).json({ message: "No file provided" });
        }
        const fileTypeModule = await import("file-type");
        const fileTypeFromBuffer = fileTypeModule.fileTypeFromBuffer;
        const detectedType = await fileTypeFromBuffer(file.buffer);
        const allowedMimeTypes = ["image/jpeg", "image/png", "image/webp", "image/gif"];
        if (!detectedType || !allowedMimeTypes.includes(detectedType.mime)) {
          return res.status(400).json({
            message: "Invalid file type. Only JPEG, PNG, WebP, and GIF images are allowed"
          });
        }
        const maxSizeBytes = 10 * 1024 * 1024;
        if (file.size > maxSizeBytes) {
          return res.status(400).json({
            message: "File too large. Maximum size is 10MB"
          });
        }
        const { productId, role } = req.body;
        if (!productId || !role) {
          return res.status(400).json({ message: "Product ID and role are required" });
        }
        const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
        if (!uuidRegex.test(productId)) {
          return res.status(400).json({ message: "Invalid product ID format" });
        }
        const validRoles = ["primary", "label", "lifestyle", "gallery"];
        if (!validRoles.includes(role)) {
          return res.status(400).json({ message: "Invalid role" });
        }
        const bucketId = process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID;
        if (!bucketId) {
          return res.status(500).json({ message: "Object storage not configured" });
        }
        const originalExt = file.originalname.split(".").pop() || "jpg";
        const safeExt = originalExt.toLowerCase().replace(/[^a-z0-9]/g, "");
        const allowedExtensions = ["jpg", "jpeg", "png", "webp", "gif"];
        const extension = allowedExtensions.includes(safeExt) ? safeExt : "jpg";
        const timestamp2 = Date.now();
        const random = Math.random().toString(36).substring(2, 8);
        const filename = `product-${productId}-${role}-${timestamp2}-${random}.${extension}`;
        const objectPath = `public/products/${filename}`;
        const bucket = objectStorageClient.bucket(bucketId);
        const bucketFile = bucket.file(objectPath);
        await bucketFile.save(file.buffer, {
          metadata: {
            contentType: file.mimetype
          }
        });
        const objectStorageService2 = new ObjectStorageService();
        const normalizedPath = await objectStorageService2.trySetObjectEntityAclPolicy(objectPath, {
          owner: "system",
          visibility: "public"
        });
        const publicUrl = `https://storage.googleapis.com/${bucketId}/${normalizedPath}`;
        const mediaData = {
          filename,
          originalFilename: file.originalname,
          objectPath,
          publicUrl,
          mimeType: file.mimetype,
          fileSize: file.size,
          category: "product-images"
        };
        const mediaRecord = await storage.createMediaLibraryFile(mediaData);
        const productMediaData = {
          productId,
          mediaId: mediaRecord.id,
          role,
          sortOrder: 0
        };
        const productMedia2 = await storage.createProductMedia(productMediaData);
        res.json({
          success: true,
          media: mediaRecord,
          productMedia: productMedia2
        });
      });
    } catch (error) {
      console.error("Error uploading product media:", error);
      res.status(500).json({ message: error instanceof Error ? error.message : "Upload failed" });
    }
  });
