      const safeJobTitle = jobTitle === "" ? null : jobTitle !== void 0 ? jobTitle : current.job_title;
      const safePhoneNumber = phoneNumber === "" ? null : phoneNumber !== void 0 ? phoneNumber : current.phone_number;
      const safeActive = active !== void 0 ? active : current.active;
