  app2.post("/api/auth/request-password-reset", async (req, res) => {
    try {
      const { email } = req.body;
      if (!email) {
        return res.status(400).json({ message: "Email is required" });
      }
      const userResult = await db.execute(sql31`
        SELECT id, email, first_name FROM platform_users WHERE email = ${email}
      `);
      if (userResult.rows.length === 0) {
        return res.json({ message: "If an account with that email exists, a password reset link has been sent." });
      }
      const user = userResult.rows[0];
      const token = crypto9.randomUUID() + "-" + crypto9.randomUUID();
      const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1e3);
      await db.execute(sql31`
        DELETE FROM password_reset_tokens WHERE user_id = ${user.id}
      `);
      await db.execute(sql31`
        INSERT INTO password_reset_tokens (user_id, token, expires_at)
        VALUES (${user.id}, ${token}, ${expiresAt})
      `);
      const resetBaseUrl = process.env.APP_URL || (process.env.REPLIT_DOMAINS?.split(",")[0] ? `https://${process.env.REPLIT_DOMAINS.split(",")[0]}` : null) || "https://nashobawinery.org";
      const resetUrl = `${resetBaseUrl}/reset-password?token=${token}`;
      if (process.env.SENDGRID_API_KEY) {
        const sgMail8 = await import("@sendgrid/mail");
        sgMail8.default.setApiKey(process.env.SENDGRID_API_KEY);
        const msg = {
          to: user.email,
          from: process.env.SENDGRID_FROM_EMAIL || "noreply@nashobawinery.com",
          subject: "Password Reset Request - Nashoba Valley Operations",
          html: `
            <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
              <h2 style="color: #7c2d12;">Password Reset Request</h2>
              <p>Hello ${user.first_name},</p>
              <p>You requested to reset your password for the Nashoba Valley Operations Platform.</p>
              <p>Click the button below to set a new password:</p>
              <a href="${resetUrl}" style="display: inline-block; background-color: #7c2d12; color: white; padding: 12px 24px; text-decoration: none; border-radius: 6px; margin: 16px 0;">Reset Password</a>
              <p style="color: #666; font-size: 14px;">This link will expire in 24 hours.</p>
              <p style="color: #666; font-size: 14px;">If you didn't request this, you can safely ignore this email.</p>
              <hr style="border: none; border-top: 1px solid #eee; margin: 24px 0;" />
              <p style="color: #999; font-size: 12px;">Nashoba Valley Operations Platform</p>
            </div>
          `
        };
        await sgMail8.default.send(msg);
        console.log("Password reset email sent to:", user.email);
      } else {
        console.log("SendGrid not configured. Reset URL:", resetUrl);
      }
      res.json({ message: "If an account with that email exists, a password reset link has been sent." });
    } catch (error) {
      console.error("Error requesting password reset:", error);
      res.status(500).json({ message: "Failed to process password reset request" });
    }
  });
  app2.get("/api/auth/verify-reset-token", async (req, res) => {
    try {
      const { token } = req.query;
      if (!token) {
        return res.status(400).json({ valid: false, message: "Token is required" });
      }
      const result = await db.execute(sql31`
        SELECT prt.*, pu.email, pu.first_name
        FROM password_reset_tokens prt
        JOIN platform_users pu ON prt.user_id = pu.id
        WHERE prt.token = ${token}
          AND prt.expires_at > NOW()
          AND prt.used_at IS NULL
      `);
      if (result.rows.length === 0) {
        return res.json({ valid: false, message: "Invalid or expired token" });
      }
      const tokenData = result.rows[0];
      res.json({ valid: true, email: tokenData.email, firstName: tokenData.first_name });
    } catch (error) {
      console.error("Error verifying reset token:", error);
      res.status(500).json({ valid: false, message: "Failed to verify token" });
    }
  });
  app2.post("/api/auth/reset-password", async (req, res) => {
    try {
      const { token, password } = req.body;
      if (!token || !password) {
        return res.status(400).json({ message: "Token and password are required" });
      }
      if (password.length < 8) {
        return res.status(400).json({ message: "Password must be at least 8 characters long" });
      }
      const tokenResult = await db.execute(sql31`
        SELECT * FROM password_reset_tokens
        WHERE token = ${token}
          AND expires_at > NOW()
          AND used_at IS NULL
      `);
      if (tokenResult.rows.length === 0) {
        return res.status(400).json({ message: "Invalid or expired reset token" });
      }
      const resetToken = tokenResult.rows[0];
      const passwordHash = await bcrypt3.hash(password, 10);
      await db.execute(sql31`
        UPDATE platform_users
        SET password_hash = ${passwordHash}, updated_at = NOW()
        WHERE id = ${resetToken.user_id}
      `);
      await db.execute(sql31`
        UPDATE password_reset_tokens
        SET used_at = NOW()
        WHERE id = ${resetToken.id}
      `);
      res.json({ message: "Password has been reset successfully" });
    } catch (error) {
      console.error("Error resetting password:", error);
      res.status(500).json({ message: "Failed to reset password" });
    }
  });
