  app2.get("/api/lms/admin/lessons/:lessonId/full", isAdmin5, async (req, res) => {
    try {
      const { lessonId } = req.params;
      const lessonResult = await db.execute(sql31`
        SELECT l.*, 
          (SELECT COUNT(*) FROM lms_quizzes WHERE lesson_id = l.id) as quiz_count
        FROM lms_lessons l
        WHERE l.id = ${lessonId}
      `);
      if (lessonResult.rows.length === 0) {
        return res.status(404).json({ message: "Lesson not found" });
      }
      const pagesResult = await db.execute(sql31`
        SELECT * FROM lms_lesson_pages 
        WHERE lesson_id = ${lessonId}
        ORDER BY sort_order ASC
      `);
      const mainBlocksResult = await db.execute(sql31`
        SELECT * FROM lms_content_blocks 
        WHERE lesson_id = ${lessonId} AND page_id IS NULL
        ORDER BY sort_order ASC
      `);
      const pageBlocksResult = await db.execute(sql31`
        SELECT * FROM lms_content_blocks 
        WHERE lesson_id = ${lessonId} AND page_id IS NOT NULL
        ORDER BY sort_order ASC
      `);
      const pages = pagesResult.rows.map((page) => ({
        ...page,
        contentBlocks: pageBlocksResult.rows.filter((block) => block.page_id === page.id)
      }));
      const quizzesResult = await db.execute(sql31`
        SELECT * FROM lms_quizzes WHERE lesson_id = ${lessonId}
      `);
      res.json({
        ...lessonResult.rows[0],
        pages,
        mainContentBlocks: mainBlocksResult.rows,
        quizzes: quizzesResult.rows
      });
    } catch (error) {
      console.error("Error fetching full lesson:", error);
      res.status(500).json({ message: "Failed to fetch lesson" });
    }
  });
