  const generateWorkOrderNumber = async () => {
    const prefix = "WO";
    const year = (/* @__PURE__ */ new Date()).getFullYear().toString().slice(-2);
    const result = await db.execute(sql31`
      SELECT COUNT(*)::integer as count FROM maintenance_work_orders 
      WHERE work_order_number LIKE ${`${prefix}${year}%`}
    `);
    const count2 = (result.rows[0]?.count || 0) + 1;
    return `${prefix}${year}-${count2.toString().padStart(5, "0")}`;
  };
