  async function fetchWebContent(url) {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 1e4);
      const response = await fetch(url, {
        signal: controller.signal,
        headers: {
          "User-Agent": "NashobaBot/1.0 (Customer Support Assistant)",
          "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8"
        }
      });
      clearTimeout(timeoutId);
      if (!response.ok) {
        console.log(`[Web Fetch] Failed to fetch ${url}: ${response.status}`);
        return "";
      }
      const html = await response.text();
      let text2 = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, "").replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "").replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&mdash;/g, "\u2014").replace(/&ndash;/g, "\u2013").replace(/\s+/g, " ").trim();
      if (text2.length > 8e3) {
        text2 = text2.substring(0, 8e3) + "... (content truncated)";
      }
      console.log(`[Web Fetch] Successfully fetched ${url}: ${text2.length} chars`);
      return text2;
    } catch (error) {
      console.log(`[Web Fetch] Error fetching ${url}:`, error.message);
      return "";
    }
  }
