  app2.get("/api/lms/courses/:courseId/quiz", isPlatformAuthenticated, async (req, res) => {
    try {
      const quizzes = await storage.getLmsQuizzes(req.params.courseId);
      const allQuestions = [];
      for (const quiz of quizzes) {
        const linkedQuestions = await storage.getLmsQuizQuestions(quiz.id);
        for (const link of linkedQuestions) {
          allQuestions.push({
            ...link.question,
            quizId: quiz.id,
            sortOrder: link.sortOrder
          });
        }
      }
      res.json(allQuestions);
    } catch (error) {
      console.error("Error fetching course quiz questions:", error);
      res.status(500).json({ message: "Failed to fetch quiz questions" });
    }
  });
  app2.post("/api/lms/admin/courses/:courseId/quiz", isPlatformAuthenticated, async (req, res) => {
    try {
      const courseId = req.params.courseId;
      let quizzes = await storage.getLmsQuizzes(courseId);
      let quiz = quizzes[0];
      if (!quiz) {
        quiz = await storage.createLmsQuiz({
          courseId,
          title: "Course Quiz",
          description: "Course assessment quiz",
          passingScore: 70,
          timeLimit: null,
          maxAttempts: 3,
          shuffleQuestions: false,
          showResults: true
        });
      }
      let banks = await storage.getLmsQuestionBanks();
      let courseBank = banks.find((b) => b.name === `Course ${courseId} Questions`);
      if (!courseBank) {
        courseBank = await storage.createLmsQuestionBank({
          name: `Course ${courseId} Questions`,
          description: "Question bank for course"
        });
      }
      const question = await storage.createLmsQuestion({
        questionBankId: courseBank.id,
        questionType: req.body.question_type || "multiple_choice",
        questionText: req.body.question,
        options: req.body.options || [],
        correctAnswer: req.body.correct_answer,
        explanation: req.body.explanation,
        points: req.body.points || 1
      });
      const existingLinks = await storage.getLmsQuizQuestions(quiz.id);
      await storage.addLmsQuizQuestion({
        quizId: quiz.id,
        questionId: question.id,
        sortOrder: existingLinks.length + 1
      });
      res.status(201).json({
        ...question,
        quizId: quiz.id,
        sortOrder: existingLinks.length + 1
      });
    } catch (error) {
      console.error("Error creating quiz question:", error);
      res.status(500).json({ message: "Failed to create quiz question" });
    }
  });
  app2.put("/api/lms/admin/quiz/:id", isPlatformAuthenticated, async (req, res) => {
    try {
      const question = await storage.updateLmsQuestion(req.params.id, {
        questionText: req.body.question,
        questionType: req.body.question_type,
        options: req.body.options,
        correctAnswer: req.body.correct_answer,
        explanation: req.body.explanation,
        points: req.body.points
      });
      if (!question) {
        return res.status(404).json({ message: "Question not found" });
      }
      res.json(question);
    } catch (error) {
      console.error("Error updating quiz question:", error);
      res.status(500).json({ message: "Failed to update quiz question" });
    }
  });
