async function seedDailyReportTemplates() {
  console.log("[Daily Reports] Checking department templates...");
  const genericFieldDefs = [
    { key: "total_reservations", label: "Total Reservations", type: "number", description: "Total number of reservations for the day", sortOrder: 1 },
    { key: "no_shows", label: "No Shows", type: "number", description: "Number of no-show reservations", sortOrder: 2 },
    { key: "walkins", label: "Walk-ins", type: "number", description: "Number of walk-in customers", sortOrder: 3 },
    { key: "walkin_tasting_bar", label: "Walk-in Tasting Bar", type: "number", description: "Walk-ins for tasting bar", sortOrder: 4 },
    { key: "walkin_tours", label: "Walk-in Tours", type: "number", description: "Walk-ins for tours", sortOrder: 5 },
    { key: "low_inventory_items", label: "Low Inventory Items (ASAP)", type: "text", description: "Items that need immediate restocking", sortOrder: 6 },
    { key: "items_86d", label: "Items 86'd", type: "text", description: "Items that are no longer available", sortOrder: 7 },
    { key: "customer_incident_reports", label: "Customer Incident Reports", type: "text", description: "Reports of customer incidents", sortOrder: 8 },
    { key: "customer_comments", label: "Customer Comments", type: "text", description: "General customer feedback", sortOrder: 9 },
    { key: "summary", label: "Summary", type: "text", description: "Daily summary notes", sortOrder: 10 },
    { key: "voids_explanations", label: "Voids and Explanations", type: "text", description: "Voided transactions with explanations", sortOrder: 11 },
    { key: "building_name", label: "Building Name", type: "text", description: "Name of building for maintenance", sortOrder: 12 },
    { key: "equipment_name", label: "Equipment Name", type: "text", description: "Equipment that needs attention", sortOrder: 13 },
    { key: "repair_maintenance_desc", label: "Repair or Maintenance Description", type: "text", description: "Description of repair or maintenance needed", sortOrder: 14 },
    { key: "location", label: "Location", type: "text", description: "Specific location reference", sortOrder: 15 },
    { key: "area_cleaned", label: "Area Cleaned", type: "text", description: "Areas that were cleaned", sortOrder: 16 },
    { key: "product_required", label: "Product Required", type: "text", description: "Products needed for restocking", sortOrder: 17 },
    { key: "incident_report", label: "Incident Report", type: "text", description: "General incident reporting", sortOrder: 18 }
  ];
  const departments2 = [
    { department: "tasting_room", departmentLabel: "Tasting Room" },
    { department: "retail", departmentLabel: "Retail" },
    { department: "the_knoll", departmentLabel: "The Knoll" },
    { department: "pavilion", departmentLabel: "Pavilion" },
    { department: "js_restaurant", departmentLabel: "J's Restaurant" },
    { department: "production", departmentLabel: "Production" },
    { department: "events", departmentLabel: "Events" },
    { department: "maintenance", departmentLabel: "Maintenance" },
    { department: "orchard", departmentLabel: "Orchard" },
    { department: "food_operations", departmentLabel: "Food Operations" }
  ];
  try {
    const existingFields = await storage.getDailyReportFieldDefinitions(false);
    const fieldIdMap = {};
    for (const fieldDef of genericFieldDefs) {
      let existingField = existingFields.find((f) => f.key === fieldDef.key);
      if (!existingField) {
        existingField = await storage.createDailyReportFieldDefinition(fieldDef);
      }
      fieldIdMap[fieldDef.key] = existingField.id;
    }
    const genericMetrics = genericFieldDefs.map((f) => ({
      key: f.key,
      label: f.label,
      type: f.type,
      isEnabled: true
    }));
    for (const dept of departments2) {
      const template = await storage.upsertDailyReportTemplate({
        department: dept.department,
        departmentLabel: dept.departmentLabel,
        metrics: genericMetrics,
        isActive: true
      });
      const existingAssignments = await storage.getDepartmentFieldAssignments(template.id);
      for (const fieldDef of genericFieldDefs) {
        const fieldId = fieldIdMap[fieldDef.key];
        const existing = existingAssignments.find((a) => a.fieldDefinitionId === fieldId);
        if (!existing && fieldId) {
          await storage.createDepartmentFieldAssignment({
            templateId: template.id,
            fieldDefinitionId: fieldId,
            isEnabled: true,
            sortOrder: fieldDef.sortOrder
          });
        }
      }
    }
    const templates = await storage.getDailyReportTemplates();
    console.log(`[Daily Reports] Department templates: ${templates.length} total`);
  } catch (error) {
    console.error("[Daily Reports] Error seeding templates:", error);
  }
}
