function parseObjectPath3(path4) {
  if (path4.startsWith("https://storage.googleapis.com/")) {
    const url = new URL(path4);
    const pathnameParts = url.pathname.split("/").filter((p) => p);
    if (pathnameParts.length < 2) {
      throw new Error("Invalid storage URL: must contain bucket and object name");
    }
    return {
      bucketName: pathnameParts[0],
      objectName: pathnameParts.slice(1).join("/")
    };
  }
  if (!path4.startsWith("/")) {
    path4 = `/${path4}`;
  }
  const pathParts = path4.split("/");
  if (pathParts.length < 3) {
    throw new Error("Invalid path: must contain at least a bucket name");
  }
  const bucketName = pathParts[1];
  const objectName = pathParts.slice(2).join("/");
  return {
    bucketName,
    objectName
  };
}
async function signObjectURL2({
  bucketName,
  objectName,
  method,
  ttlSec
}) {
  const REPLIT_SIDECAR_ENDPOINT2 = "http://127.0.0.1:1106";
  const request = {
    bucket_name: bucketName,
    object_name: objectName,
    method,
    expires_at: new Date(Date.now() + ttlSec * 1e3).toISOString()
  };
  const response = await fetch(
    `${REPLIT_SIDECAR_ENDPOINT2}/object-storage/signed-object-url`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify(request)
    }
  );
  if (!response.ok) {
    throw new Error(
      `Failed to sign object URL, errorcode: ${response.status}, make sure you're running on Replit`
    );
  }
  const { signed_url: signedURL } = await response.json();
  return signedURL;
}

